body:
This will cause issues with macOS embedded window focus (running game in the editor). Since embedded process display server also has no `FEATURE_MOUSE` set.

It is because of this check:

https://github.com/godotengine/godot/blob/084a2caa05119b625a99b6b51d44b459a26362de/scene/main/viewport.cpp#L1508

We probably should use another flag for this, since embedded display server has mouse support.

<details>
<summary>Patch</summary>

```diff
diff --git a/doc/classes/DisplayServer.xml b/doc/classes/DisplayServer.xml
index 4665bacd27..8e434247b4 100644
--- a/doc/classes/DisplayServer.xml
+++ b/doc/classes/DisplayServer.xml
@@ -2825,8 +2825,11 @@
 		</constant>
 		<constant name="FEATURE_PIP_MODE" value="36" enum="Feature">
 			Display server supports putting the application in picture-in-picture mode. [b]Android[/b]
 		</constant>
+		<constant name="FEATURE_EMBEDDED" value="37" enum="Feature">
+			Display server is embedding windows to another process. [b]macOS[/b]
+		</constant>
 		<constant name="ROLE_UNKNOWN" value="0" enum="AccessibilityRole" deprecated="Use [AccessibilityServer] instead.">
 			Unknown or custom role.
 		</constant>
 		<constant name="ROLE_DEFAULT_BUTTON" value="1" enum="AccessibilityRole" deprecated="Use [AccessibilityServer] instead.">
diff --git a/platform/macos/display_server_macos_embedded.mm b/platform/macos/display_server_macos_embedded.mm
index 393d587a4f..becfa64afd 100644
--- a/platform/macos/display_server_macos_embedded.mm
+++ b/platform/macos/display_server_macos_embedded.mm
@@ -412,9 +412,9 @@
 		case DisplayServerEnums::FEATURE_IME:
 		case DisplayServerEnums::FEATURE_CUSTOM_CURSOR_SHAPE:
 			// case DisplayServerEnums::FEATURE_HIDPI:
 			// case DisplayServerEnums::FEATURE_ICON:
-			// case DisplayServerEnums::FEATURE_MOUSE:
+		case DisplayServerEnums::FEATURE_MOUSE:
 		case DisplayServerEnums::FEATURE_HDR_OUTPUT:
 		case DisplayServerEnums::FEATURE_MOUSE_WARP:
 			// case DisplayServerEnums::FEATURE_NATIVE_DIALOG:
 			// case DisplayServerEnums::FEATURE_NATIVE_ICON:
@@ -424,8 +424,9 @@
 			// case DisplayServerEnums::FEATURE_ORIENTATION:
 			// case DisplayServerEnums::FEATURE_VIRTUAL_KEYBOARD:
 		case DisplayServerEnums::FEATURE_TEXT_TO_SPEECH:
 			// case DisplayServerEnums::FEATURE_TOUCHSCREEN:
+		case DisplayServerEnums::FEATURE_EMBEDDED:
 			return true;
 		default:
 			return false;
 	}
diff --git a/scene/main/viewport.cpp b/scene/main/viewport.cpp
index 4efd6a5f91..00e5e5ab8b 100644
--- a/scene/main/viewport.cpp
+++ b/scene/main/viewport.cpp
@@ -1504,9 +1504,9 @@ Vector2 Viewport::get_mouse_position() const {
 	if (get_section_root_viewport() != SceneTree::get_singleton()->get_root()) {
 		// Rely on the most recent mouse coordinate from an InputEventMouse in push_input.
 		// In this case get_screen_transform is not applicable, because it is ambiguous.
 		return gui.last_mouse_pos;
-	} else if (DisplayServer::get_singleton()->has_feature(DisplayServerEnums::FEATURE_MOUSE)) {
+	} else if (DisplayServer::get_singleton()->has_feature(DisplayServerEnums::FEATURE_MOUSE) && !DisplayServer::get_singleton()->has_feature(DisplayServerEnums::FEATURE_EMBEDDED)) {
 		Transform2D xform = get_screen_transform_internal(true);
 		if (xform.determinant() == 0) {
 			// Screen transform can be non-invertible when the Window is minimized.
 			return Vector2();
diff --git a/servers/display/display_server_enums.h b/servers/display/display_server_enums.h
index 4dc862f937..664f2df564 100644
--- a/servers/display/display_server_enums.h
+++ b/servers/display/display_server_enums.h
@@ -79,8 +79,9 @@ enum Feature {
 	FEATURE_SELF_FITTING_WINDOWS,
 	FEATURE_ACCESSIBILITY_SCREEN_READER,
 	FEATURE_HDR_OUTPUT,
 	FEATURE_PIP_MODE,
+	FEATURE_EMBEDDED,
 };

 /* RENDERING DEVICE */

diff --git a/servers/display/display_server.cpp b/servers/display/display_server.cpp
index 90cd5962e9..789ae06ad3 100644
--- a/servers/display/display_server.cpp
+++ b/servers/display/display_server.cpp
@@ -1775,8 +1775,9 @@ void DisplayServer::_bind_methods() {
 	BIND_ENUM_CONSTANT(DisplayServerEnums::FEATURE_SELF_FITTING_WINDOWS);
 	BIND_ENUM_CONSTANT(DisplayServerEnums::FEATURE_ACCESSIBILITY_SCREEN_READER);
 	BIND_ENUM_CONSTANT(DisplayServerEnums::FEATURE_HDR_OUTPUT);
 	BIND_ENUM_CONSTANT(DisplayServerEnums::FEATURE_PIP_MODE);
+	BIND_ENUM_CONSTANT(DisplayServerEnums::FEATURE_EMBEDDED);

 #ifndef DISABLE_DEPRECATED
 	BIND_ENUM_CONSTANT(DisplayServerEnums::ROLE_UNKNOWN);
 	BIND_ENUM_CONSTANT(DisplayServerEnums::ROLE_DEFAULT_BUTTON);
```

</details>
